<h1 class="h3 mb-4"><?= $subject ? 'Editar assunto' : 'Novo assunto' ?></h1><form method="post" action="/assuntos/salvar" class="card card-body bg-white"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><?php if ($subject): ?><input type="hidden" name="id" value="<?= (int) $subject['id'] ?>"><?php endif; ?><div class="row g-3"><div class="col-12"><label class="form-label">Título</label><input class="form-control" name="titulo" maxlength="255" required value="<?= htmlspecialchars($subject['titulo'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-6"><label class="form-label">Configuração</label><select class="form-select" name="configuracao_id"><option value="">Sem configuração</option><?php foreach ($configs as $config): ?><option value="<?= (int) $config['id'] ?>" <?= (($subject['configuracao_id'] ?? null) == $config['id']) ? 'selected' : '' ?>><?= htmlspecialchars($config['nome'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Ordem</label><input class="form-control" type="number" min="0" name="ordem" value="<?= (int) ($subject['ordem'] ?? 0) ?>"></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach (['pendente', 'processando', 'concluido', 'cancelado'] as $status): ?><option <?= ($subject['status'] ?? 'pendente') === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">Instruções adicionais</label><textarea class="form-control" name="instrucoes" rows="4"><?= htmlspecialchars($subject['instrucoes'] ?? '', ENT_QUOTES, 'UTF-8') ?></textarea></div><div class="col-md-6"><label class="form-label">Não executar antes de</label><input class="form-control" type="datetime-local" name="nao_antes_de" value="<?= $subject && $subject['nao_antes_de'] ? date('Y-m-d\TH:i', strtotime($subject['nao_antes_de'])) : '' ?>"></div></div><div class="mt-4"><button class="btn btn-primary">Salvar</button> <a class="btn btn-outline-secondary" href="/assuntos">Cancelar</a></div></form>
